__global__ void matmul(const float* A, const float* B, float* C,
                       int M, int N, int K) {
    __shared__ float sA[16][16];
    __shared__ float sB[16][16];

    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int row = blockIdx.y * 16 + ty;
    int col = blockIdx.x * 16 + tx;

    float sum = 0.0f;
    for (int k = 0; k < K; k += 16) {
        if (row < M && k + tx < K)
            sA[ty][tx] = A[row * K + (k + tx)];
        else
            sA[ty][tx] = 0.0f;

        if (col < N && k + ty < K)
            sB[ty][tx] = B[(k + ty) * N + col];
        else
            sB[ty][tx] = 0.0f;

        __syncthreads();

        for (int i = 0; i < 16; ++i)
            sum += sA[ty][i] * sB[i][tx];

        __syncthreads();
    }

    if (row < M && col < N)
        C[row * N + col] = sum;
}
